local js_code = [[
    (function() {
        if (!document.getElementById('ultra-lite-optimization')) {
            const style = document.createElement('style');
            style.id = 'ultra-lite-optimization';
            style.innerHTML = `
                /* 1. ПОЛНОЕ УБИЙСТВО ВСЕХ АНИМАЦИЙ */
                /* Снижает нагрузку на процессор до 0% в режиме простоя */
                *, *::before, *::after {
                    animation-duration: 0.01ms !important;
                    animation-iteration-count: 1 !important;
                    transition-duration: 0.01ms !important;
                    scroll-behavior: auto !important;
                }

                /* 2. УДАЛЕНИЕ ТЯЖЕЛЫХ ЭФФЕКТОВ (Главная причина лагов) */
                /* Блюр (размытие) - самый ресурсоемкий эффект для телефонов */
                * {
                    backdrop-filter: none !important;
                    -webkit-backdrop-filter: none !important;
                    box-shadow: none !important;
                    text-shadow: none !important;
                }

                /* 3. УДАЛЕНИЕ ФОНОВ И ПАТТЕРНОВ */
                /* Удаляем тяжелый повторяющийся SVG-фон в меню чатов */
                div[style*="background-image: url(\\"data:image/svg+xml"] {
                    background-image: none !important;
                    background-color: #2d1b3d !important; /* Оставляем чистый темный цвет */
                }

                /* 4. ОТКЛЮЧЕНИЕ АНИМИРОВАННЫХ РАМОК У БОТОВ И VIP-ПОЛЬЗОВАТЕЛЕЙ */
                /* Убираем 10 слоев крутящихся градиентов вокруг аватарок */
